mapper.select:
SELECT DISTINCT d.APPLICANT_NO from meicloud_usrm_cloud_biz_sou.scc_sou_project p
                                        JOIN meicloud_usrm_cloud_biz_sou.scc_npm_sou_demand d on d.PROJECT_ID = p.PROJECT_ID
where d.PROJECT_ID = #{projectId}

SELECT DISTINCT v.VENDOR_NAME vendorName, f.ORDER_DOC_ID orderDocId from meicloud_usrm_cloud_biz_sou.scc_sou_order_file f
                                                                             JOIN meicloud_usrm_cloud_biz_sou.scc_sou_vendor v on v.VENDOR_ID = f.VENDOR_ID and f.PROJECT_ID = v.PROJECT_ID AND v.PROJECT_ID = #{projectId}
where f.FILE_TYPE IN ('TECH_BID', 'BUS_BID', 'TECH_QUA_PERF', 'TECH_OTHER', 'BUS_OTHER', 'BUSINESS_FILE')

SELECT DISTINCT s.FILEUPLOAD_ID fileuploadId, q.VENDOR_NAME vendorName  from meicloud_usrm_cloud_biz_sou.scc_sou_question q
                                         join meicloud_usrm_cloud_biz_base.scc_base_scene_file s on s.SCENE_MODULE_CODE='SCENE_SOU_QUESTION_FILE_ATTACHMENT' and s.BUSINESS_ID = q.QUESTION_ID
where q.PROJECT_ID = #{projectId}

SELECT DISTINCT m.PAY_VOUCHER_FILE_ID payVoucherFileId,m.VENDOR_NAME vendorName from meicloud_usrm_cloud_biz_sou.scc_npm_sou_margin m
where m.PROJECT_ID =#{projectId}
  and m.PAY_VOUCHER_FILE_ID is not NULL

SELECT DISTINCT f.FILE_TYPE fileType, f.sou_doc_id souDocId from meicloud_usrm_cloud_biz_sou.scc_sou_file f
where f.FILE_TYPE IN ('APPLY', 'BID','ARCHIVE','TALK')
  and f.PROJECT_ID = #{projectId}

SELECT DISTINCT a.ATTACH_ID from meicloud_usrm_cloud_biz_sou.scc_npm_inspect_attach a
                                     JOIN meicloud_usrm_cloud_biz_sou.scc_npm_inspect p on p.INSPECT_ID = a.INSPECT_ID
where p.BIDING_ID = #{projectId}

SELECT distinct f.FILEUPLOAD_ID fileuploadId, f.FILE_FULLNAME fileFullname, f.FILE_SOURCE_NAME fileSourceName from meicloud_usrm_cloud_biz_base.scc_file_fileupload f
where f.FILEUPLOAD_ID IN
#{item}
